     1	{# Одна строка ленты. Тот же шаблон отдаёт SSE-кадр `feed`, поэтому события,
     2	   пришедшие до открытия страницы (из буфера шины), и события после неё
     3	   выглядят одинаково. #}
     4	{% set p = event.payload %}
     5	<li class="ev ev-{{ event.kind }}">
     6	  <time>{{ event.ts.strftime('%H:%M:%S') }}</time>
     7	  {%- if event.kind == 'run_started' %}
     8	    <b>Заход #{{ p.run_id }} начат</b> — {{ 'вручную' if p.trigger == 'manual' else 'по расписанию' }}
     9	  {%- elif event.kind == 'counters' %}
    10	    Батч выбран: {{ p.claimed }} игр, фаза {{ p.phase }}, страниц {{ p.pages }}
    11	  {%- elif event.kind == 'game_started' %}
    12	    <span class="mark">→</span> {{ p.title or p.slug }}
    13	  {%- elif event.kind == 'game_done' %}
    14	    <span class="mark ok">✓</span> {{ p.title or p.slug }}
    15	  {%- elif event.kind == 'game_failed' %}
    16	    <span class="mark fail">✗</span> {{ p.title or p.slug }} — {{ p.error }}
    17	  {%- elif event.kind == 'llm_call' %}
    18	    <span class="mark">≈</span> резюме: вызовов {{ p.calls }}{% if p.failures %}, неудачных {{ p.failures }}{% endif %} — {{ p.title or p.slug }}
    19	  {%- elif event.kind == 'letsplay' %}
    20	    <span class="mark">▶</span> летсплей: {{ p.status }} — {{ p.title or p.slug }}
    21	  {%- elif event.kind == 'run_finished' %}
    22	    <b>Заход {% if p.run_id %}#{{ p.run_id }} {% endif %}завершён</b> — {{ p.status }}
    23	    {%- if p.status not in ('skipped_locked',) %}, ok {{ p.ok }}, ошибок {{ p.failed }}{% endif %}
    24	    {%- if p.error %} <span class="fail">{{ p.error }}</span>{% endif %}
    25	  {%- else %}
    26	    {{ event.kind }} {{ p }}
    27	  {%- endif %}
    28	</li>
