     1	{% extends "base.html" %}
     2	{% block title %}{{ game.title }} — Metacritic digest{% endblock %}
     3	{% block content %}
     4	  <article class="game" data-slug="{{ game.slug }}">
     5	    <div class="head">
     6	      <div class="cover">
     7	        {% if game.cover_path %}
     8	          <img src="{{ cover_url(game.cover_path) }}" alt="{{ game.title }}"
     9	               width="226" height="332" decoding="async">
    10	        {% else %}
    11	          <span class="cover-empty muted">без обложки</span>
    12	        {% endif %}
    13	      </div>
    14	
    15	      <div class="meta">
    16	        <h1>{{ game.title }}</h1>
    17	
    18	        <dl class="facts">
    19	          {% if game.developer %}<dt>Разработчик</dt><dd>{{ game.developer }}</dd>{% endif %}
    20	          {% if game.publisher %}<dt>Издатель</dt><dd>{{ game.publisher }}</dd>{% endif %}
    21	          {% if game.release_date %}<dt>Релиз</dt><dd>{{ game.release_date.strftime('%d.%m.%Y') }}</dd>{% endif %}
    22	          {% if game.genres_cache %}<dt>Жанры</dt><dd>{{ game.genres_cache|join(', ') }}</dd>{% endif %}
    23	          {% if game.esrb_rating %}<dt>ESRB</dt><dd>{{ game.esrb_rating }}</dd>{% endif %}
    24	        </dl>
    25	
    26	        {% if game.description %}
    27	          <p class="description">{{ game.description }}</p>
    28	        {% endif %}
    29	      </div>
    30	    </div>
    31	
    32	    <section id="platforms">
    33	      <h2>Платформы и оценки</h2>
    34	      {% if game.platforms %}
    35	        <table class="platforms">
    36	          <thead>
    37	            <tr><th>Платформа</th><th>Metascore</th><th>Userscore</th></tr>
    38	          </thead>
    39	          <tbody>
    40	            {% for p in game.platforms %}
    41	              <tr{% if p.is_lead %} class="lead"{% endif %}>
    42	                <td>
    43	                  {{ p.platform_name }}
    44	                  {% if p.is_lead %}<span class="tag muted">ведущая</span>{% endif %}
    45	                </td>
    46	                <td>
    47	                  {% if p.metascore is not none %}
    48	                    <span class="score metascore">{{ p.metascore }}</span>
    49	                    <span class="muted count">
    50	                      {{ p.metascore_count or 0 }} крит.{% if p.metascore_sentiment %} · {{ p.metascore_sentiment }}{% endif %}
    51	                    </span>
    52	                  {% else %}
    53	                    <span class="muted">—</span>
    54	                  {% endif %}
    55	                </td>
    56	                <td>
    57	                  {% if p.userscore is not none %}
    58	                    <span class="score userscore">{{ '%.1f'|format(p.userscore) }}</span>
    59	                    <span class="muted count">
    60	                      {{ p.userscore_count or 0 }} польз.{% if p.userscore_sentiment %} · {{ p.userscore_sentiment }}{% endif %}
    61	                    </span>
    62	                  {% else %}
    63	                    <span class="muted">—</span>
    64	                  {% endif %}
    65	                </td>
    66	              </tr>
    67	            {% endfor %}
    68	          </tbody>
    69	        </table>
    70	      {% else %}
    71	        <p class="muted">Платформы не заполнены.</p>
    72	      {% endif %}
    73	    </section>
    74	
    75	    {% if game.video_url %}
    76	      <section id="video">
    77	        <h2>Видео</h2>
    78	        {# Плеер Metacritic (jwplayer) отдаётся без X-Frame-Options, встраивается
    79	           напрямую. Ссылка рядом — на случай, если у зрителя блокируются iframe. #}
    80	        <div class="video"><iframe src="{{ game.video_url }}" allowfullscreen
    81	                                   referrerpolicy="no-referrer" title="Трейлер {{ game.title }}"></iframe></div>
    82	        <p class="muted"><a href="{{ game.video_url }}" target="_blank" rel="noopener">Открыть видео отдельно</a></p>
    83	      </section>
    84	    {% endif %}
    85	
    86	    <section id="review-summaries">
    87	      <h2>Что говорят об игре</h2>
    88	      {# Резюме собирает LLM на обходе каталога (T-30); здесь только чтение из
    89	         БД. Блок рисуется всегда: «резюме ещё нет» — тоже состояние, и оно
    90	         должно быть видно, а не выглядеть как отсутствующая секция. #}
    91	      <div class="summaries">
    92	        {% for audience, heading in [('critic', 'Критики'), ('user', 'Пользователи')] %}
    93	          {% set s = summaries.get(audience) %}
    94	          <div class="summary" data-audience="{{ audience }}">
    95	            <h3>{{ heading }}</h3>
    96	            {% if s and s.status == 'ok' %}
    97	              {% if s.liked %}
    98	                <p class="verdict good">Нравится</p>
    99	                <ul class="liked">{% for point in s.liked %}<li>{{ point }}</li>{% endfor %}</ul>
   100	              {% endif %}
   101	              {% if s.disliked %}
   102	                <p class="verdict bad">Не нравится</p>
   103	                <ul class="disliked">{% for point in s.disliked %}<li>{{ point }}</li>{% endfor %}</ul>
   104	              {% else %}
   105	                <p class="muted">Заметных претензий в отзывах нет.</p>
   106	              {% endif %}
   107	              {% if s.tldr %}<p class="tldr">{{ s.tldr }}</p>{% endif %}
   108	              <p class="muted origin">
   109	                {{ 'Рецензий' if audience == 'critic' else 'Отзывов' }}: {{ s.quotes_count }}
   110	                {%- if s.generated_at %} · собрано {{ s.generated_at.strftime('%d.%m.%Y') }}{% endif %}
   111	              </p>
   112	            {% elif s and s.status == 'no_data' %}
   113	              <p class="muted">Отзывов пока нет.</p>
   114	            {% else %}
   115	              {# llm_failed или строки ещё нет: пользователю важно одно — что
   116	                 это временно. Текст ошибки на экран не выносим (design §5.5). #}
   117	              <p class="muted">Резюме не готово, обновится при следующем обходе.</p>
   118	            {% endif %}
   119	          </div>
   120	        {% endfor %}
   121	      </div>
   122	    </section>
   123	
   124	    {# Похожие игры (T-33/T-34): только то, что уже есть в своей базе. Пустой
   125	       результат — не состояние, а отсутствие блока: у игры может не быть жанров,
   126	       а на молодой базе пересечений может не найтись вовсе (design §3.5). #}
   127	    {% if similar %}
   128	      <section id="similar-games">
   129	        <h2>Похожие игры</h2>
   130	        <ul class="similar">
   131	          {% for other in similar %}
   132	            <li>
   133	              <a class="cover" href="/game/{{ other.slug }}">
   134	                {% if other.cover_path %}
   135	                  <img src="{{ cover_url(other.cover_path) }}" alt="{{ other.title }}"
   136	                       width="113" height="166" loading="lazy" decoding="async">
   137	                {% else %}
   138	                  <span class="cover-empty muted">без обложки</span>
   139	                {% endif %}
   140	              </a>
   141	              <a class="title" href="/game/{{ other.slug }}">{{ other.title }}</a>
   142	              <p class="scores">
   143	                {% if other.best_metascore is not none %}
   144	                  <span class="score metascore" title="Metascore">{{ other.best_metascore }}</span>
   145	                {% endif %}
   146	                {% set n = other.shared_genres %}
   147	                <span class="muted">{{ n }}
   148	                  {%- if n % 10 == 1 and n % 100 != 11 %} общий жанр
   149	                  {%- elif 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14 %} общих жанра
   150	                  {%- else %} общих жанров{% endif %}</span>
   151	              </p>
   152	            </li>
   153	          {% endfor %}
   154	        </ul>
   155	      </section>
   156	    {% endif %}
   157	
   158	    {# Летсплей (доп. часть 1, T-44). Блок отдельный от «Видео» выше: там
   159	       официальный трейлер Metacritic, здесь — прохождение с YouTube и
   160	       заключение по его пересказу (OQ-10).
   161	
   162	       Рисуется только при `status='ok'`: у `not_found`/`service_error` нет ни
   163	       заключения, ни ролика, а «летсплей не нашёлся» — не та новость, ради
   164	       которой стоит занимать место в карточке. Фича best-effort, и карточка без
   165	       неё — нормальное состояние (ADR-8). #}
   166	    {% if letsplay and letsplay.status == 'ok' %}
   167	      <section id="letsplay">
   168	        <h2>Летсплей</h2>
   169	        {% if letsplay.conclusion %}
   170	          <p class="conclusion">{{ letsplay.conclusion }}</p>
   171	        {% endif %}
   172	        <p class="source">
   173	          <a href="{{ letsplay.video_url }}" target="_blank" rel="noopener nofollow">
   174	            {{ letsplay.video_title or 'Смотреть на YouTube' }}</a>
