   125	       результат — не состояние, а отсутствие блока: у игры может не быть жанров,
   126	       а на молодой базе пересечений может не найтись вовсе (design §3.5). #}
   127	    {% if similar %}
   128	      <section id="similar-games">
   129	        <h2>Похожие игры</h2>
   130	        <ul class="similar">
   131	          {% for other in similar %}
   132	            <li>
   133	              <a class="cover" href="/game/{{ other.slug }}">
   134	                {% if other.cover_path %}
   135	                  <img src="{{ cover_url(other.cover_path) }}" alt="{{ other.title }}"
   136	                       width="113" height="166" loading="lazy" decoding="async">
   137	                {% else %}
   138	                  <span class="cover-empty muted">без обложки</span>
   139	                {% endif %}
   140	              </a>
   141	              <a class="title" href="/game/{{ other.slug }}">{{ other.title }}</a>
   142	              <p class="scores">
   143	                {% if other.best_metascore is not none %}
   144	                  <span class="score metascore" title="Metascore">{{ other.best_metascore }}</span>
   145	                {% endif %}
   146	                {% set n = other.shared_genres %}
   147	                <span class="muted">{{ n }}
   148	                  {%- if n % 10 == 1 and n % 100 != 11 %} общий жанр
   149	                  {%- elif 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14 %} общих жанра
   150	                  {%- else %} общих жанров{% endif %}</span>
   151	              </p>
   152	            </li>
   153	          {% endfor %}
   154	        </ul>
   155	      </section>
   156	    {% endif %}
   157	
   158	    {# Летсплей (доп. часть 1, T-44). Блок отдельный от «Видео» выше: там
   159	       официальный трейлер Metacritic, здесь — прохождение с YouTube и
   160	       заключение по его пересказу (OQ-10).
   161	
   162	       Рисуется только при `status='ok'`: у `not_found`/`service_error` нет ни
   163	       заключения, ни ролика, а «летсплей не нашёлся» — не та новость, ради
   164	       которой стоит занимать место в карточке. Фича best-effort, и карточка без
   165	       неё — нормальное состояние (ADR-8). #}
   166	    {% if letsplay and letsplay.status == 'ok' %}
   167	      <section id="letsplay">
   168	        <h2>Летсплей</h2>
   169	        {% if letsplay.conclusion %}
   170	          <p class="conclusion">{{ letsplay.conclusion }}</p>
   171	        {% endif %}
   172	        <p class="source">
   173	          <a href="{{ letsplay.video_url }}" target="_blank" rel="noopener nofollow">
   174	            {{ letsplay.video_title or 'Смотреть на YouTube' }}</a>
   175	          <span class="muted">
   176	            {%- if letsplay.channel %} · {{ letsplay.channel }}{% endif %}
   177	            {%- if letsplay.view_count %} · {{ letsplay.view_count|views }} просмотров{% endif %}
   178	          </span>
   179	        </p>
   180	        {% if letsplay.retelling %}
   181	          {# Пересказ длинный и машинный — по умолчанию свёрнут: в карточке
   182	             главное заключение, а пересказ нужен, чтобы его проверить. #}
   183	          <details class="retelling">
   184	            <summary>Пересказ ролика</summary>
   185	            <div class="retelling-text">{{ letsplay.retelling }}</div>
   186	          </details>
   187	        {% endif %}
   188	      </section>
   189	    {% endif %}
   190	
   191	    <p class="muted back"><a href="/games">← ко всем играм</a></p>
   192	  </article>
   193	
   194	  <style>
   195	    .game .head { display:flex; gap:24px; flex-wrap:wrap; }
   196	    .game .cover { flex:0 0 226px; aspect-ratio:226/332; background:var(--line);
   197	                   border:1px solid var(--line); border-radius:10px; overflow:hidden; }
   198	    .game .cover img { width:100%; height:100%; object-fit:cover; display:block; }
   199	    .cover-empty { display:flex; height:100%; align-items:center; justify-content:center; font-size:13px; }
   200	    .game .meta { flex:1 1 380px; min-width:0; }
   201	    .game h1 { margin:0 0 12px; font-size:26px; line-height:1.2; }
   202	    .game h2 { font-size:16px; margin:28px 0 10px; }
   203	    .facts { display:grid; grid-template-columns:max-content 1fr; gap:4px 14px; margin:0 0 16px; font-size:14px; }
   204	    .facts dt { color:var(--muted); }
   205	    .facts dd { margin:0; }
   206	    .description { margin:0; white-space:pre-line; }
   207	    table.platforms { border-collapse:collapse; width:100%; font-size:14px; }
   208	    table.platforms th, table.platforms td { text-align:left; padding:8px 10px; border-bottom:1px solid var(--line); }
   209	    table.platforms th { color:var(--muted); font-weight:500; }
   210	    table.platforms tr.lead td:first-child { font-weight:600; }
   211	    .tag { font-size:12px; margin-left:6px; }
   212	    .count { font-size:12px; margin-left:6px; }
   213	    .score { display:inline-block; min-width:30px; padding:2px 6px; border-radius:5px;
   214	             font-weight:600; text-align:center; color:#111; }
   215	    .metascore { background:#ffcc33; }
   216	    .userscore { background:#7ec8a0; }
   217	    .summaries { display:flex; gap:24px; flex-wrap:wrap; }
   218	    .summary { flex:1 1 300px; min-width:0; padding:14px 16px; border:1px solid var(--line); border-radius:10px; }
   219	    .summary h3 { margin:0 0 10px; font-size:15px; }
