cd /Users/ivan/Desktop/testing_task; .venv/bin/python - <<'PY'
import re, urllib.request, collections
BASE="https://ai-engineer-task-production.up.railway.app"
def get(u):
    return urllib.request.urlopen(urllib.request.Request(BASE+u, headers={"User-Agent":"audit/1.0"}), timeout=30).read().decode()

slugs=[]
for p in range(1,9):
    slugs += re.findall(r'<a class="title" href="/game/([^"]+)"', get(f"/games?page={p}"))
slugs = list(dict.fromkeys(slugs))
print(f"карточек: {len(slugs)}")

def state(block):
    if 'class="verdict good"' in block or 'class="liked"' in block: return "ok (есть резюме)"
    if "Отзывов пока нет" in block: return "no_data (отзывов нет)"
    if "Резюме не готово" in block: return "не готово"
    return "?"

cnt = collections.Counter(); examples = {}
for s in slugs:
    card = get(f"/game/{s}")
    for aud in ("critic", "user"):
        m = re.search(rf'data-audience="{aud}">(.*?)</div>', card, re.S)
        st = state(m.group(1)) if m else "нет блока"
        cnt[(aud, st)] += 1
        examples.setdefault((aud, st), s)

for (aud, st), n in sorted(cnt.items()):
    print(f"  {aud:7} {st:22} {n:4}   пример: {examples[(aud,st)]}")
PY
